function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Each menu category is wrapped in a .user-items-list element
  $('.user-items-list').each(function () {
    const $wrapper = $(this);

    // --- Determine section heading ---
    let section = null;

    // 1) Look for the preceding .list-section-title that contains the heading
    const $titleDiv = $wrapper.prev('.list-section-title');
    if ($titleDiv.length) {
      const titleText = $titleDiv.find('strong').text();
      section = titleText ? cleanText(titleText) : null;
    }

    // 2) Fallback: parse the JSON stored in data-current-context
    if (!section) {
      const ctxAttr = $wrapper.attr('data-current-context');
      if (ctxAttr) {
        try {
          const data = JSON.parse(ctxAttr);
          if data && data.sectionTitle) {
            section = cleanText(data.sectionTitle);
          }
        } catch (_) { /* ignore */ }
      }
    }

    // --- Process each dish in this category ---
    $wrapper.find('li.list-item').each(function () {
      const $li = $(this);

      // Name
      const $nameEl = $li.find('h2.list-item-content__title');
      const nameRaw = $nameEl.text();
      const name = nameRaw ? cleanText(nameRaw) : null;
      if (!name) return; // skip items without a name

      // Description and price live in .list-item-content__description
      const $descWrapper = $li.find('.list-item-content__description');
      let description = null;
      let price = null;

      if ($descWrapper.length) {
        // Clone to manipulate without affecting the original
        const $clone = $descWrapper.clone();
        // Remove the price <strong> so we can get pure description text
        $clone.find('strong').remove();
        const descText = $clone.text();
        description = descText ? cleanText(descText) : null;

        // Price: take the text of the remaining <strong>
        const $priceStrong = $descWrapper.find('strong');
        const priceText = $priceStrong.text().trim();
        price = priceText ? parsePrice(priceText) : null;
      }

      // Build a dedup key
      const key = `${section ?? ''}|${name}|${description ?? ''}|${price ?? ''}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
```

